@Component
public class ResourceLifecycle {
    private final ResourceLeaseRepository leases;
    private final IncidentTaskRepository tasks;
    private final Clock clock;

    /** 到期门禁：任务持有 ACTIVE 租约且当前时刻已进入到期点时，同事务固化
        任务 AUTHORIZATION_EXPIRED + 租约 EXPIRED + EXPIRE/EXECUTE_INTERCEPT 事件，
        然后抛 AuthorizationExpiredException（dontRollbackOn 提交证据）。 */
    public void assertAuthorizationValid(IncidentTask task, String actor, String interceptedOperation) {
        var active = leases.findActiveByTask(task.id());
        if (active.isEmpty()) return;
        ResourceLease lease = active.get();
        Instant now = clock.instant();
        if (!lease.expiredAt(now)) return;
        tasks.markAuthorizationExpired(task.id(), now);
        leases.markExpired(lease.id(), now);
        leases.insertEvent(new ResourceEvent(0L, task.incidentId(), task.id(), lease.resourceKey(),
                ResourceEventType.EXPIRE, lease.authVersion(), null, actor, now,
                "授权到期判定", now));
        if (interceptedOperation != null) {
            leases.insertEvent(... EXECUTE_INTERCEPT, lease.authVersion(), null, actor, now, interceptedOperation ...);
        }
        throw new AuthorizationExpiredException("资源授权已到期: " + lease.resourceKey(),
                details map);
    }
