@Transactional
public ResourceLeaseView assign(String incidentKey, String taskKey, String actor, ResourceAssignRequest req) {
    String commandKey = requireText(req.commandKey(), "commandKey");
    String resourceKey = requireText(req.resourceKey(), "resourceKey");
    if (req.authorizationVersion() == null || req.authorizationVersion() < 1) throw badRequest("authorizationVersion 必须 >= 1");
    if (req.expiresAt() == null) throw badRequest("expiresAt 不能为空");
    Instant expiresAt = req.expiresAt().truncatedTo(MICROS);
    Incident incident = lockIncident(incidentKey);
    IncidentTask task = tasks.findByKey(incident.id(), taskKey).orElseThrow(notFound);
    return idempotency.run(commandKey, "resource_assign",
        hash(incidentKey, taskKey, actor, resourceKey, String.valueOf(version), expiresAt.toString()),
        ResourceLeaseView.class,
        () -> requireCommander(incident, actor),   // preCheck: permission before placeholder
        () -> {
            if (task.status() == AUTHORIZATION_EXPIRED) throw conflict("授权已到期的任务禁止再次分配");  // 409
            if (task.status() == DONE || task.status() == CANCELLED) throw conflict("终态...");
            // expiresAt must be after assignment moment
            Instant now = now();
            if (!expiresAt.isAfter(now)) throw badRequest with details {assignedAt: now, expiresAt, requirement}
            // existing active lease?
            if (leases.findActiveByTask(task.id()).isPresent()) throw conflict("任务已持有生效中的资源授权");
            leases.lockResource(resourceKey, now);
            var occupying = leases.listOccupying(resourceKey, now).stream()
                .filter(l -> l.incidentId() != incident.id()).toList();
            if (!occupying.isEmpty()) throw conflict("资源仍被其他事件占用", details with occupying incident? );
            long id = leases.insertLease(new ResourceLease(0, task.id(), incident.id(), resourceKey, version, actor, now, expiresAt, ACTIVE, null, null, now, now));
            leases.insertEvent(ASSIGN event oldVersion null newVersion version);
            return toLeaseView(leases.findLatestByTask(task.id()).orElseThrow(), task.taskKey());
        });
}
