List<ResourceLease> incidentLeases = leases.listByIncident(incident.id());  // all leases
while (changed) {
    changed = false;
    for (ResourceLease l : incidentLeases) {
        if (l.status() == ACTIVE && closureResources.contains(l.resourceKey()) && closureTaskIds.add(l.taskId())) {
            // a same-incident task sharing a resource joins the closure; its other resources join too
        }
    }
    // add resources of newly added tasks
    for (ResourceLease l : incidentLeases) {
        if (l.status() == ACTIVE && closureTaskIds.contains(l.taskId()) && closureResources.add(l.resourceKey())) changed = true;
    }
}
