                .isEqualTo("AUTHORIZATION_EXPIRED");
        // 同键重放首次结果；换键再评估返回当前状态且不重复产生证据
        ResourceLeaseView replay = service.checkAuthorization("INC-E3", "T-1",
                new TaskActionRequest(checkKey));
